    PrivatePool c;

    function setUp() public {
        c = new PrivatePool(address(this), address(this), address(this));
    }

    function testRegression_property() public {
        MockNFT nft = new MockNFT();

        try c.initialize(
            address(0),
            address(nft),
            100 ether,
            10 ether,
            0,
            0,
            bytes32(0),
            false,
            false
        ) {
            assertTrue(true, "Reference initialize succeeded");
        } catch {
            assertTrue(false, "Buggy initialize reverted");
        }
    }
}

